/* Kiln & Co. Grey stoneware page, three glazes, one dip line. See DESIGN.md. */

:root {
  /* clay */
  --clay: oklch(0.945 0.006 250);       /* page: fired grey stoneware */
  --clay-foot: oklch(0.86 0.012 250);   /* bare clay below a dip line */
  --speck: oklch(0.55 0.02 60 / 0.55);  /* iron speckle in raw clay */
  --ink: oklch(0.24 0.02 260);
  --muted: oklch(0.43 0.02 260);

  /* glazes */
  --cobalt: oklch(0.38 0.14 264);
  --cobalt-deep: oklch(0.31 0.12 264);
  --celadon: oklch(0.78 0.07 170);
  --tenmoku: oklch(0.27 0.04 50);
  --on-glaze: oklch(0.97 0.008 250);
  --on-glaze-muted: oklch(0.86 0.03 260);

  --ring: var(--cobalt);

  --display: "Bricolage Grotesque", "Avenir Next", "Segoe UI", system-ui, sans-serif;
  --body: "Source Serif 4", Charter, "Iowan Old Style", Georgia, serif;

  /* scale 1.333 */
  --step-0: 1.0625rem;
  --step-1: 1.417rem;
  --step-2: 1.889rem;
  --step-3: 2.518rem;

  --ease-out: cubic-bezier(0.22, 1, 0.36, 1);
}

*, *::before, *::after { box-sizing: border-box; }

html {
  scroll-behavior: smooth;
  -webkit-text-size-adjust: 100%;
}

body {
  margin: 0;
  background: var(--clay);
  color: var(--ink);
  font-family: var(--body);
  font-size: var(--step-0);
  line-height: 1.6;
  font-optical-sizing: auto;
}

::selection { background: var(--celadon); color: var(--ink); }

h1, h2, h3 {
  font-family: var(--display);
  line-height: 1.1;
  text-wrap: balance;
  margin: 0;
}

p { margin: 0; text-wrap: pretty; }

a { color: inherit; text-underline-offset: 0.2em; text-decoration-thickness: 1px; }

:focus-visible {
  outline: 3px solid var(--ring);
  outline-offset: 3px;
  border-radius: 2px;
}

.wrap {
  width: min(100% - 2.5rem, 72rem);
  margin-inline: auto;
}

.skip {
  position: absolute;
  left: 1rem;
  top: -10rem;
  z-index: 10;
  background: var(--on-glaze);
  color: var(--ink);
  padding: 0.75rem 1rem;
  font-family: var(--display);
  font-weight: 600;
}
.skip:focus { top: 1rem; }

/* Buttons */

.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: 2.75rem;
  padding: 0.6rem 1.25rem;
  border-radius: 999px;
  font-family: var(--display);
  font-weight: 600;
  font-size: 1rem;
  line-height: 1.2;
  text-decoration: none;
  touch-action: manipulation;
  transition: background-color 180ms var(--ease-out), transform 100ms var(--ease-out);
}
.btn:active { transform: translateY(1px) scale(0.98); }

.btn--light { background: var(--on-glaze); color: var(--cobalt-deep); }
.btn--glaze { background: var(--cobalt); color: var(--on-glaze); }

@media (hover: hover) {
  .btn--light:hover { background: oklch(0.9 0.03 250); }
  .btn--glaze:hover { background: var(--cobalt-deep); }
  .nav__links a:hover,
  .link-on-glaze:hover { text-decoration-thickness: 2px; }
}

/* Hero: a glazed band that ends in a dip line */

.hero {
  --ring: var(--on-glaze);
  position: relative;
  background: var(--cobalt);
  color: var(--on-glaze);
  padding-bottom: 2rem;
  margin-bottom: 4.5rem;
}

.nav {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 0.5rem 2rem;
  padding-block: 1.25rem;
}

.wordmark {
  font-family: var(--display);
  font-weight: 800;
  font-size: var(--step-1);
  letter-spacing: -0.02em;
  text-decoration: none;
  margin-right: auto;
}
.wordmark span { font-weight: 500; }

.nav__links {
  display: flex;
  gap: 0.25rem 1.5rem;
  list-style: none;
  margin: 0;
  padding: 0;
  font-family: var(--display);
  font-weight: 500;
}
.nav__links a {
  display: inline-flex;
  align-items: center;
  min-height: 2.75rem;
  text-decoration-color: transparent;
}
.nav__links a:hover { text-decoration-color: currentColor; }

.hero__body {
  display: grid;
  grid-template-columns: minmax(0, 1.15fr) minmax(0, 0.85fr);
  gap: 3rem;
  align-items: end;
  padding-block: 3rem 1rem;
}

.hero h1 {
  font-size: clamp(2.6rem, 1.2rem + 5.4vw, 5.5rem);
  font-weight: 800;
  letter-spacing: -0.035em;
  line-height: 0.98;
  max-width: 12ch;
}

.hero__sub {
  margin-top: 1.5rem;
  max-width: 36rem;
  font-size: var(--step-1);
  line-height: 1.5;
  color: var(--on-glaze);
}

.hero__actions {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 1rem 1.75rem;
  margin-top: 2.25rem;
}

.link-on-glaze {
  display: inline-flex;
  align-items: center;
  min-height: 2.75rem;
  font-family: var(--display);
  font-weight: 600;
}

.hero__photo { margin: 0; }
.hero__photo figcaption { color: var(--on-glaze-muted); }

.dip {
  display: block;
  width: 100%;
  fill: currentColor;
}

.dip--hero {
  position: absolute;
  left: 0;
  top: 100%;
  height: clamp(2rem, 4vw, 3.75rem);
  color: var(--cobalt);
  transform-origin: top;
  animation: pour 800ms var(--ease-out) both;
}

@keyframes pour {
  from { transform: scaleY(0.35); }
  to { transform: scaleY(1); }
}

/* Photo frames: glazed top, bare speckled foot. Placeholders until real photos arrive. */

figure { margin: 0; }

figcaption {
  margin-top: 0.75rem;
  font-size: 0.9375rem;
  font-style: italic;
  color: var(--muted);
}

.frame {
  --glaze: var(--cobalt);
  position: relative;
  aspect-ratio: 4 / 3;
  border-radius: 0.5rem;
  overflow: hidden;
  background:
    linear-gradient(var(--glaze), var(--glaze)) top / 100% 72% no-repeat,
    radial-gradient(circle, var(--speck) 0.9px, transparent 1.4px) 0 0 / 23px 19px,
    radial-gradient(circle, var(--speck) 0.7px, transparent 1.2px) 9px 7px / 37px 31px,
    var(--clay-foot);
}
.frame .dip {
  position: absolute;
  top: 72%;
  left: 0;
  height: 14%;
  color: var(--glaze);
}
.frame--tall { aspect-ratio: 4 / 5; }
.frame--wide { aspect-ratio: 16 / 10; }
.frame--celadon { --glaze: var(--celadon); }
.frame--tenmoku { --glaze: var(--tenmoku); }
.frame--cobalt { --glaze: var(--cobalt); }

/* Workshops: a board of test tiles */

.section-head {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(0, 1fr);
  gap: 1rem 3rem;
  align-items: end;
  margin-bottom: 3rem;
}
.section-head h2,
.studio h2,
.book h2 {
  font-size: var(--step-3);
  font-weight: 700;
  letter-spacing: -0.025em;
}
.section-head p { max-width: 34rem; }

.tiles {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 2.5rem;
  list-style: none;
  margin: 0;
  padding: 0;
}

.workshop {
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
}

.tile {
  position: relative;
  height: 11rem;
  margin-bottom: 0.75rem;
  border-radius: 0.375rem;
  overflow: hidden;
  background:
    radial-gradient(circle, var(--speck) 0.9px, transparent 1.4px) 0 0 / 23px 19px,
    radial-gradient(circle, var(--speck) 0.7px, transparent 1.2px) 9px 7px / 37px 31px,
    var(--clay-foot);
}
.tile__glaze {
  position: relative;
  height: var(--dip);
  background: var(--glaze);
}
.tile__glaze .dip {
  position: absolute;
  top: 100%;
  left: 0;
  height: 1.1rem;
  color: var(--glaze);
}

.workshop h3 {
  font-size: var(--step-2);
  font-weight: 700;
  letter-spacing: -0.02em;
}
.workshop__hours {
  font-family: var(--display);
  font-weight: 600;
  margin-top: -0.25rem;
}
.workshop__when { color: var(--muted); }

.workshop__price {
  margin-top: auto;
  padding-top: 0.5rem;
  color: var(--muted);
}
.price {
  font-family: var(--display);
  font-size: var(--step-2);
  font-weight: 700;
  color: var(--ink);
  font-variant-numeric: tabular-nums;
  margin-right: 0.25rem;
}
.workshop .btn { align-self: flex-start; }

/* Studio */

.studio { margin-top: 7rem; }

.studio__inner {
  display: grid;
  grid-template-columns: minmax(0, 0.7fr) minmax(0, 1.3fr);
  gap: 3rem;
  align-items: start;
}
.studio__text { position: sticky; top: 2rem; }
.studio__text p { margin-top: 1.25rem; max-width: 30rem; }

.gallery {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 2.5rem 1.5rem;
}
.gallery__main { grid-column: 1 / -1; }
.gallery figure:nth-child(3) { margin-top: 4rem; }

/* Book */

.book {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(0, 1fr);
  gap: 2rem 3rem;
  align-items: end;
  margin-top: 7rem;
  margin-bottom: 8rem;
  padding-top: 3rem;
  border-top: 1px solid oklch(0.62 0.015 250);
}
.book h2 { scroll-margin-top: 2rem; }
.book h2:focus { outline: none; }
.book h2:focus-visible { outline: 3px solid var(--ring); }
.book__text p { margin-top: 1.25rem; max-width: 34rem; }
.book__note { color: var(--muted); }

.contact {
  margin: 0;
  display: grid;
  gap: 1.5rem;
}
.contact dt {
  font-family: var(--display);
  font-weight: 600;
  color: var(--muted);
}
.contact dd {
  margin: 0.25rem 0 0;
  font-family: var(--display);
  font-size: var(--step-2);
  font-weight: 700;
  letter-spacing: -0.015em;
  overflow-wrap: anywhere;
}
.contact a { color: var(--cobalt); }

/* Footer: tenmoku, with glaze pooled along its top edge */

.footer {
  --ring: var(--on-glaze);
  position: relative;
  background: var(--tenmoku);
  color: var(--on-glaze);
  padding-block: 4rem 3rem;
  line-height: 1.7;
}
.dip--footer {
  position: absolute;
  bottom: calc(100% - 1px);
  left: 0;
  height: clamp(1.5rem, 3vw, 2.5rem);
  color: var(--tenmoku);
  transform: scaleY(-1);
}

.footer__inner {
  display: grid;
  grid-template-columns: 1.2fr repeat(3, minmax(0, 1fr));
  gap: 2rem;
}
.wordmark--footer { margin: 0; font-size: var(--step-2); line-height: 1.1; }
.footer__label {
  font-size: 1rem;
  font-weight: 600;
  color: var(--on-glaze-muted);
  margin-bottom: 0.5rem;
  letter-spacing: 0.01em;
}
.footer address { font-style: normal; }

/* Narrower screens */

@media (max-width: 60rem) {
  .hero__body,
  .section-head,
  .studio__inner,
  .book { grid-template-columns: minmax(0, 1fr); }
  .hero__photo { max-width: 26rem; }
  .studio__text { position: static; }
  .tiles { grid-template-columns: minmax(0, 1fr); gap: 3.5rem; }
  .tile { height: 9rem; }
  .footer__inner { grid-template-columns: repeat(2, minmax(0, 1fr)); }
}

@media (max-width: 34rem) {
  .nav__links { order: 3; width: 100%; }
  .gallery { grid-template-columns: minmax(0, 1fr); }
  .gallery figure:nth-child(3) { margin-top: 0; }
  .footer__inner { grid-template-columns: minmax(0, 1fr); }
}

@media (prefers-reduced-motion: reduce) {
  html { scroll-behavior: auto; }
  .dip--hero { animation: none; }
  .btn:active { transform: none; }
}

